// npm run demo:audio — renders the sample member recordings in eval/fixtures/audio/*.script.json with macOS voices
// (`say`), joins the lines with ffmpeg into public/samples/*.mp3, and writes their exact transcripts to
// src/lib/transcribe/samples.generated.ts so the demo can read them with no transcription key.
// Needs macOS, ffmpeg (with libmp3lame) and ffprobe. Re-running gives byte-identical MP3s only on the same machine,
// so commit the MP3s and the generated file together.
import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import { mkdirSync, mkdtempSync, readFileSync, readdirSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { scriptToTranscript, type SampleScript } from "../../src/lib/transcribe/sampleScript";
import type { Transcript } from "../../src/lib/transcribe/types";

type Sample = SampleScript & { file: string; title: string; who: string; where: string; participants: string };

const FIXTURES = "eval/fixtures/audio";
const OUT = "public/samples";
const RATE = "185"; // words per minute: a little brisker than say's default, closer to conversation

const run = (cmd: string, args: string[]) => execFileSync(cmd, args, { stdio: ["ignore", "pipe", "pipe"] }).toString();

function render(sample: Sample, work: string): { mp3: string; duration: number } {
  const parts: string[] = [];
  // 0.45 s of silence between turns, so diarization sees clean speaker changes.
  const gap = join(work, "gap.wav");
  run("ffmpeg", ["-y", "-f", "lavfi", "-i", "anullsrc=r=22050:cl=mono", "-t", "0.45", gap]);
  sample.lines.forEach((l, i) => {
    const aiff = join(work, `l${i}.aiff`);
    const wav = join(work, `l${i}.wav`);
    run("say", ["-v", l.voice, "-r", RATE, "-o", aiff, l.text]);
    run("ffmpeg", ["-y", "-i", aiff, "-ar", "22050", "-ac", "1", wav]);
    parts.push(wav, gap);
  });
  const list = join(work, "list.txt");
  writeFileSync(list, parts.map((p) => `file '${p}'`).join("\n"));
  const mp3 = join(OUT, sample.file);
  run("ffmpeg", ["-y", "-f", "concat", "-safe", "0", "-i", list, "-ac", "1", "-ar", "22050", "-codec:a", "libmp3lame", "-b:a", "64k", "-map_metadata", "-1", "-fflags", "+bitexact", mp3]);
  const duration = Number(run("ffprobe", ["-v", "error", "-show_entries", "format=duration", "-of", "default=nw=1:nk=1", mp3]).trim());
  return { mp3, duration: Math.round(duration * 10) / 10 };
}

mkdirSync(OUT, { recursive: true });
const recordings: { file: string; title: string; who: string; where: string; participants: string }[] = [];
const transcripts: Record<string, Transcript> = {};
for (const f of readdirSync(FIXTURES).filter((n) => n.endsWith(".script.json")).sort()) {
  const sample = JSON.parse(readFileSync(join(FIXTURES, f), "utf8")) as Sample;
  const work = mkdtempSync(join(tmpdir(), "pma-audio-"));
  try {
    const { mp3, duration } = render(sample, work);
    const sha = createHash("sha256").update(readFileSync(mp3)).digest("hex");
    transcripts[sha] = scriptToTranscript(sample, duration);
    recordings.push({ file: sample.file, title: sample.title, who: sample.who, where: sample.where, participants: sample.participants });
    console.log(`${mp3}: ${duration}s, sha256 ${sha.slice(0, 12)}…`);
  } finally {
    rmSync(work, { recursive: true, force: true });
  }
}

writeFileSync("src/lib/transcribe/samples.generated.ts", `// Generated by \`npm run demo:audio\` (scripts/demo/make-sample-audio.ts). Do not edit by hand.
// The bundled sample recordings in public/samples and their exact transcripts, keyed by file SHA-256, so the demo
// can read them with no transcription key.
import type { Transcript } from "./types";

export const SAMPLE_RECORDINGS: { file: string; title: string; who: string; where: string; participants: string }[] = ${JSON.stringify(recordings, null, 2)};

export const SAMPLE_TRANSCRIPTS: Record<string, Transcript> = ${JSON.stringify(transcripts, null, 2)};
`);
console.log(`Wrote ${recordings.length} samples to src/lib/transcribe/samples.generated.ts`);
